package com.edunexa.app
import android.os.Bundle
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import com.edunexa.app.data.AttendanceRepository
import java.text.SimpleDateFormat
import java.util.*
class AttendanceActivity:AppCompatActivity(){private val repo=AttendanceRepository();private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt();override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(18),dp(18),dp(18))};setContentView(ScrollView(this).apply{addView(root)});root.addView(TextView(this).apply{text="Attendance";textSize=27f;setTypeface(typeface,1)});val date=EditText(this).apply{hint="Date YYYY-MM-DD";setText(SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date()))};root.addView(date);val status=TextView(this).apply{text="Loading students…";setPadding(0,dp(8),0,dp(12))};root.addView(status);repo.schoolStudents({students->status.text=if(students.isEmpty())"No connected students" else "${students.size} student(s)";students.forEach{(id,name)->val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;setPadding(dp(8),dp(8),dp(8),dp(8))};row.addView(TextView(this).apply{text=name;textSize=16f},LinearLayout.LayoutParams(0,dp(52),1f));row.addView(Button(this).apply{text="Present";isAllCaps=false;setOnClickListener{repo.save(id,name,date.text.toString(),true){_,m->Toast.makeText(this@AttendanceActivity,m,Toast.LENGTH_SHORT).show()}}});row.addView(Button(this).apply{text="Absent";isAllCaps=false;setOnClickListener{repo.save(id,name,date.text.toString(),false){_,m->Toast.makeText(this@AttendanceActivity,m,Toast.LENGTH_SHORT).show()}}});root.addView(row)}},{status.text=it})}}
